    "sourceSignature": "",
    "excerpt": "香，做為一種溝通物質，飄散的白煙宛若一條逃逸路線，連接著我們的現在、過去與未來。香頭透過觀看香的燃勢，為問事者答疑解惑，抵減人間殘酷；巫者追隨一襲白煙穿梭在天人之際，孕育著夢幻空間。"
