    "excerpt": "新冠疫情所向披靡，全人類都被逼進前所未見的局面。氣機導引從5月15日上午十點半接到三級警戒政令後，立即宣布封館停課。隨後，五月底、六月初，入門班教練的視訊課，以及張老師對東醫家族大群體的視訊課…"
