    "excerpt": "越南香系很豐富，尤其南部產量大，也是好香的大宗產地，因此沉香研究者必須了解越南的地理、地質、產區分佈狀態；與惠安產區的寮國、柬埔寨、緬甸、泰國等其他四國相較，越南的香最豐富，涵蓋其他四國香系。…"
