    "excerpt": "練功以來，我們聽過許多練功的階段論，像是「百日築基，十月懷胎，三年哺乳，九年面壁」、「練精化氣，練氣還神，練神還虛，練虛合道」、「移爐換鼎，移鼎換爐」、「下丹田，中丹田，上丹田」等，這些都是古…"
