    "excerpt": "張愛玲曾經在〈中國人的宗教〉一文中寫到：「就因為對一切都懷疑，中國文學裡瀰漫著大的悲哀。只有在物質的細節上，它得到歡悅——因此《金瓶梅》、《紅樓夢》仔仔細細開出整桌的菜單，毫無倦意，不為什麼，…"
