    "excerpt": "根據聯合國教科文組織統計，《道德經》是除了《聖經》以外被譯成外國文字發行量最多的經典著作。然而，《道德經》所涵蓋的思想範疇，與它的實踐層面，至今並未全然被理解，至於普遍的實踐，恐怕就更難企及了…"
