    "excerpt": "氣機導引的野外教室已落成啟用，張老師也立即展開接近大自然的第一堂課，落實了東醫氣機導引飲食、起居、運動、情緒、接近大自然的概念。走進全台灣混沌靈力最強的原始森林中，打破六根的慣性，向大自然學習…"
