    "excerpt": "聞香的時候，面對每一塊香都像是久別重逢，和它進行時空的對話。每塊香到你手上，都是一次的因果。你看到這塊香若是因，最後的果就是你內心的感受。你聞到的不只是一種香味，而是一個情境，一個香的世界。你…"
