    "excerpt": "本期電子報四篇〈如是我聞〉上課記錄，兩篇專欄，雖是從不同的角度揭示練功要旨，但最終的目標，是「幹父之蠱」、「幹母之蠱」——藉此難得之身，把男性、女性歷代祖先留在我身上的基因，再次清洗乾淨。"
