    "slug": "202107-2107-2-3",
    "image": "/assets/articles/202107/202107-img-004.png?v=539662",
    "file": "/home/runner/work/_temp/source_articles/202107/Gmail/2107-2-3蕭瑞玲.docx",
    "status": "approved",
    "sourceModified": "2021-07-07T07:41:54.0000000Z",
