    "excerpt": "藥有針對性，生什麼病就吃什麼藥，不過每種藥都有它的副作用。沉香自古就是一味中藥，有它的藥性，但不會有副作用。由現代化學分析可了解沉香的主要成份，為沉香療效找到科學證據。不過沉香除了物質面，更重…"
