    "excerpt": "品香、識香、悟香，使我們盡可能地接近不可見的真實，同時並非無視於其中味、道、氣的細膩、撩動，以及變化生成，還有勾引出對永遠不再的「往事」、「記憶」與「故土」的綿綿鄉愁。譬如，5月13日，在台芬…"
