    "excerpt": "「愛不能放在對方身上」，課堂上初聽這句話，先是楞了幾秒，隨即明白了，明白了過去自以為的種種委屈，明白了一再重複的不明白。什麼是愛？什麼是愛的方式？我們傾注了一生心力在愛，愛彷彿是我們人生最重要…"
