    "excerpt": "每個人都會呼吸，小嬰兒從呱呱墜地後吸入第一口清氣，開啟了生命內環境和外環境的連結。生命需要陽光、空氣和水；空氣由口鼻、咽喉、氣管、支氣管直下進入肺泡而進行氣體交換，需要呼吸肌群的通力合作，也有…"
