    "excerpt": "疫情三級警戒期間重讀《紅樓夢》與《金瓶梅》是一件喜樂之事，在此紛亂的時刻，如何把持住內心深刻地凝視神性與人性，同時產生悲憫之心，小說引發的時空哲學，其實與現實是極為連結的。"
