    "excerpt": "上一期的圖靈集，我們談到了練功的次第，那是從五年、十年、二十年甚至更長的時間軸來看，會有哪幾個階段的進展。假如每一次的練功只有20分鐘，那20分鐘內有沒有什麼樣的次第呢？那又是什麼樣的過程呢？…"
