    "excerpt": "固定的專欄、固定幾位作者，對編輯來說，這是最安穩舒適的做法，可是，你自己知道，長久下去，這樣準死！東醫家族人才濟濟，個個是高手，有必要把大家一個個推出來站台亮相，所以，由編輯群設計的每月專題，…"
