    "excerpt": "小方是一個今年剛滿九歲，留著短髮愛笑又愛吃的三年級小女生。平常總有著一堆不著邊際的有趣想法。最近她喜歡上了貓巧可這套書，這一天她抱著一本書提出了一個問題："
