    "excerpt": "人們在閱讀時，免不了沿著筆者所編織出來的字句遊歷在故事裡，或多或少也將自身的人生經驗帶入其中，但往往僅止於字面內容上的體會．然而，透過張老師《道德經》的步步引導，回頭再次閱讀《老人與海》這本經…"
