    "excerpt": "編輯的工作就像編織，拿到什麼材料，就編出什麼樣的織品。這一期電子報，隱隱有點測試自己，也測試大家的意思。所以，一開始丟出每月專題的徵稿啟事，就沒打算積極邀稿。果然，不論是主動投稿的，或是熱心同…"
