    "excerpt": "從開始有機會到雪山坑，就看見房子四週懸掛著密密麻麻的蜘蛛網，去了幾次，蜘蛛網清了又結、結了又清，原以為就這樣了，大自然，本該如此！不料老師一聲令下：「劃清界限」，最近再看房子架構上的蜘蛛網居然…"
