    "excerpt": "「鋒刃邊緣」電影中，屆臨退役的選手卡姐，在擊劍職業生涯中，能在最後一役奪得金牌，是她最強烈的渴望。面對一路指導訓練的學妹小拉，小拉心中亦知道這是卡姐最後一戰，而自己還年輕，還有許多四年可以挑戰…"
