    "excerpt": "大自然有春夏秋冬，人有生老病死，不同時期有不同的生命樣貌。道家的鼎爐之學用下、中、上三個丹田練養人之精氣神。「百日築基」概括人生的養生、學老、養病、學死，讓人在血肉個體中活出自己，最終返還道法…"
