    "excerpt": "疫情緊繃，剛好遇到張老師上山閉關潛修，我們卻沒得躲閃，還得在看得見的確診數字與看不見的病毒羽翅之間，繼續前行。張老師臨行前落下一句話——練功最後不是要得道成佛作上帝，而是成為「界域之主」！"
