    "excerpt": "痛，是來自身體最真實的訊息，在我們透過動作感受九大關節的同時，這樣的訊息便會以不同的形式在不同的身體部位呈現；不論是脹痛、刺痛、絞痛甚至埋藏在深層的隱隱作痛，每一種痛，都夾帶著我們在生活中累積…"
