    "excerpt": "編按：雪山坑會所啟用時，隱居於台東池上山水間的書法家蕭春生先生，應張良維老師之請，特書〈專氣至柔〉、〈上善若水〉匾額兩幅，懸掛於練功房樓梯處，以示提醒。四早班學員、中研院民族所余安邦老師日前參…"
