    "excerpt": "原來，前幾年把道德經練到身體空間裡的練習和體悟，竟是這樣無聲無息奇妙地轉化到生活裡～即使還在表層，但總算也碰到邊了。大家有沒有覺得有點安慰，功沒白練咧？"
