    "excerpt": "莫仁維承接中國工程學會111年年會時，打電話給我說要表演，我還沒有弄清楚怎麼回事就說：「好啊！」表演內容也沒問，有哪些人也不知，這是基於多年學員的信任，與他合辦活動的組織能力，以及當年被逼著表…"
