    "excerpt": "棋楠紋路通常是一條條絲狀，油脂與纖維夾雜，像白棋這種生木棋楠就看得出來。棋楠埋在土裡，但時間不夠久，還沒有碳化，就叫作綠棋、紫棋，削下去有黏黏的感覺。黃土沉本身也是棋楠樹，以前把黃土沉都稱為黃…"
