    "excerpt": "這次心血來潮，參加了一晚班和六早班聯合舉辦的雪山坑2022歲末嬉遊活動，主辦同學精心策劃每一個單元，加上大家集思廣益的結果，大家玩得很開心，\n收獲滿滿。活動結束坐車回台北，我剛好坐在主辦同學旁…"
