    "excerpt": "無極讓活動更圓滿\n從籌備到舉辦，我們一行人只開了四次會，不同的人一起發想出三天的活動，人員安排、活動進行方式、音樂播放等無不細細討論安排，但實際執行起來卻有意想不到的不按理出牌．原本想讓身體機…"
