    "excerpt": "跟著張老師練氣機導引已經十幾年了，練功除了是讓自己更懂得放鬆的身體保健，藉由練功還有聽張老師講道，也拓展了我的視野、結交了志趣相投的好同學，在記憶中留下許多難忘的美好時光。"
