    "excerpt": "依照慣例，種子班學員都會在歲末之際，錄製1分鐘的談話，可以是檢討、期許、懺悔或任何內容，總結過去一年，然後將錄音檔放上班級的群組。今年也不例外，大多數學員都跟著這麼做了，反正今年也不選武林盟主…"
