    "excerpt": "人的觀念來自大腦對事物的解讀與判斷，充滿了習性與根器的影響。像大腦的想像，眼耳鼻舌身意的根識運作，都會引發情緒作用，內心只是大腦錯誤的邏輯結果，讓人很難跳脫既有的觀念。"
