    "excerpt": "我們常勸人家說該「放下」了，也常自我安慰說終於「解脫」了，真的有這麼簡單嗎？我們先來看看「放下」、「解脫」背後的邏輯，在執行「放下」這個動作之前要有個條件，就是要先「拿起來」，你要先拿起什麼東…"
