    "excerpt": "莫仁維，人稱莫帥，也是第二屆武林盟主。何其有幸，他從二十四歲一接觸到氣機導引，就知道這是他一直在尋找的真功夫！兩年半前，他接管父親所創的工程顧問公司，員工有700多人。每天公事及會議不斷，但他…"
