    "excerpt": "入門班同學一定搞不懂，為什麼有時候會聽到說，我們這個學門叫做「氣機導引」，有時候又說是「無極（內息導引）」？勉強言之，「氣機導引」就是包含十八套功法動作的身體哲學，「無極（內息導引）」則是包含…"
