    "excerpt": "五感人間\n\n拉開鐵門，推開落地玻璃門，把室內電燈全部打開，走進廁所、練功房開抽風機換氣，拿起掃把將室內外地板掃過一遍，花草也確認澆水後，擦桌子整理玻璃商品櫃，點燃一捲紅土沉香環香，放在室外香爐…"
