    "excerpt": "三月金融市場的大新聞應該就是美國兩家銀行倒閉，以及老牌投資銀行瑞士信貸被購併的事件吧，似乎08年金融海嘯的劇本又將重演。政府快速介入，並且信誓旦旦保證有足夠工具與信心應對可能風險，暫時穩住市場…"
