    "excerpt": "第一次跟鄭素蘭及姚崑宗夫妻檔近距離接觸，正好在他倆52周年結婚紀念日，那天一些師兄姊大家約去新店泡温泉，吃中飯，順便去內洞步道走走，沒想到那天正好也是他們的金婚紀念日！很難得看到像他們這樣結縭…"
