    "sourceSignature": "v2|37f7eb9ad0e9e6cf30b980fdce96f04b01ee6f042b937d490f02b7d68acd98a7|",
    "excerpt": "大象：「執大象，天下往。往而不害，安平太。樂與餌，過客止。道之出口，淡乎其無味，視之不足見，聽之不足聞，用之不足既。」"
