    "slug": "202306-2306-7",
    "image": "/assets/pixabay/pixabay-5438382.jpg?v=5438382",
    "file": "/home/runner/work/_temp/source_articles/202306/2306-7體證道德經.docx",
    "status": "approved",
    "sourceModified": "2023-06-08T02:32:08.0000000Z",
