    "slug": "202306-2306-8",
    "image": "/assets/pixabay/pixabay-5824948.jpg?v=5824948",
    "file": "/home/runner/work/_temp/source_articles/202306/2306-8心田集.docx",
    "status": "approved",
    "sourceModified": "2023-06-08T02:32:08.0000000Z",
    "author": "文稿彙整、鄭雅靜",
