    "excerpt": "氣機導引的學員常年慢活，偶有肢體違和也能稍加自理，身體日用而不知，不覺老之將至。曾幾何時，台灣社會從8.1位青壯年人口扶養1名老人，到如今遞減為3.4位青壯人口要扶養1名老人，無論是個人、家庭…"
