    "excerpt": "道德經第三十九章：昔之得一者：天得一以清，地得一以寧，神得一以靈，谷得一以盈，萬物得一以生，侯王得一以為天下貞。其致之也，謂天無以清將恐裂，地無以寧將恐廢，神無以靈將恐歇，谷無以盈將恐竭，萬物…"
