    "excerpt": "之前探討的概念主要圍繞著週期兩個字，但是比較偏重較短的信貸週期上。自從二十年前網路泡沫，各國長期實施零利率疊加量化寬鬆政策後，股價與其說是反映基本面，不如說是反映資金與信心的變化。有題材、有資…"
