    "excerpt": "這次的採訪很特別，是東醫母女檔，不是夫妻檔！因為母親賴鈺晶的關係，羅星如早在國中時就跟著媽媽到會館上氣機導引入門課一期。羅星如目前雖然只有23歲，卻是個老靈魂，她坦言平時沒特別愛練功，卻喜歡聽…"
