    "excerpt": "你一出生就長得好可愛，八字又好重，大家都說你這輩子一定狠好命。你小時候好乖，好聽大人的話，大家都說你是乖寶寶。你上學了，你好聰明，考試常考一百分，你也好聽老師的話，時常當選模範生，是個標準的好…"
