    "excerpt": "最近看到十多年前在阿里山田野調查的照片，驚覺自己早忘了當時的模樣，照片裡的人雖然年輕，卻滿臉愁容，蒼白瘦弱，駝背又水腫，頹廢又病懨懨的。回想那時受到武俠小說的影響，總覺得應該去練個氣功什麼的來…"
