    "excerpt": "身體練功的層次是境界，境界即為火候。練功有三種火候，分別是弱火境、真火境、心火境。三種練功的境界都根植在身體且同時存在，練下丹田提高能量，中丹田鍛鍊心性，上丹田是增長智慧。丹田是身體無所不在的…"
