    "excerpt": "在道的周天循環中有百日築基、練精化氣、練炁化神、練神還虛，乃至練虛合道、道法自然六個階段，同時也會經歷換力期、換氣期和換意期。鼎、爐概念在此可視為行為論。通過身體做動作，從體神經系統鍛鍊專注到…"
