    "excerpt": "前幾天看了阮經天主演的《周處除三害》，近期的台灣電影佳作，情感張力都拉得剛好不會太過。劇中最搶眼的一個道具應該就是桂林仔阿嬤留下來的那一隻粉紅色小豬卡通錶，看得我也想去買一隻來戴！"
