    "excerpt": "自從莊子藉輪扁之口嘲諷所謂的聖賢之書，只是「古人之糟粕耳」，後代的知識份子就再三提醒自己，讀書求知，得要「舊學商量加邃密，新知培養轉深沉」。其實，「加邃密」、「轉深沉」的路徑，就是回到自己，跟…"
