    "excerpt": "本期電子報的文章篇數較少，但每篇文稿的份量都很重，重，不是因為篇幅長，而是內容含金量很高，必須仔細地、慢慢品味。尤其是〈如是我聞——超越常人，成為超人〉，因為是從種子班張老師的上課逐字稿仔細裁…"
