    "excerpt": "人生步入晚年，你只剩下壽命，所以要跟壽命賽跑。你現在擁有的意義就是你活著，你死了就什麼都沒有意義了，除非你長智慧。長智慧了，到最後1分鐘都還擁有無限的未來，這叫「時空扭曲」。"
