    "excerpt": "你們要讀波粒二象論，這是顯學。物理學一百年來突飛猛進，從經典物理到量子物理，會是主導人類思想重要的改變。這不是從論語到孟子、再到王陽明這樣微小的改變，它是顛覆性的改變。"
