    "excerpt": "這幾天在雪山坑跟園藝專家一起剪樹。環境就像人需要整理，剪樹時每一刀都預留它未來的樣子，跟剪頭髮不一樣。剪頭髮是剪了又長再剪，剪樹是剪到一個程度以後，它就定型了。"
