    "excerpt": "十多年前某次參加三天兩夜活動，與治療偶然相遇的第一次，卻是無比慘痛的經驗。那日場地受限需要席地而坐，而我卻因不明原因突然無法盤腿，老師一開始就詢問有沒有人身體不適，身旁好心的同學居然幫我舉手，…"
