    "excerpt": "美國降息拉開了四海歡騰普天同慶的樂觀氣氛，然而讓大家下巴掉下來的是中國在九月二十六日中央政治局會議的神操作，形成一個奇觀是美國降息，人民幣升值，中國股市衝破頂。這項操作趕在十一長假前，中國指數…"
