    "excerpt": "無論是屏東靜心會館集體信念的緣分，還是「如是我聞」裡張老師提到的信，以及這麼多年來親眼看到張老師所有事的發生，信真的可以變成人類生命中的一把寶劍，讓你無往不利。這不是迷信，這是信光，透過全覺能…"
