    "sourceSignature": "v2|e1b1ba3005a09cff40c1050d3faaaf628048624e8cda244a86a0e95835d852cc|",
    "excerpt": "知者不言，言者不知。塞其兌，閉其門。挫其銳，解其紛，和其光，同其塵，是謂玄同。 故不可得而親，不可得而疏；不可得而利，不可得而害；不可得而貴，不可得而賤；故為天下貴。"
