    "excerpt": "我看過一個視頻，說一個人在跟一張桌子講話，講到活活氣死；不是桌子聽不懂，是這個講者很笨，他不應該跟桌子講話，應該等到這張桌子被丟棄在深山裡，腐朽化成碎料，再被微生物分解成泥土，之後長出向日葵，…"
