    "excerpt": "無極是在身體裡面形成很深、很重的壓縮、折疊，又不能有力量，可以下地（人法地）再反彈上天，到無限遠的空間裡去。所以，是在天地人三才之中形成內在的覺。這一切訓練都得讓心靜；心無感覺、大腦想太多、身…"
