    "excerpt": "張老師的新書《大地瑰寶奇楠 古今香見—迎接嫁接時代》隆重出版了！這本書凝聚遠近相接引的因緣、集結眾多孜孜不倦的綿薄之力而成。從文字、圖片看，講的是作者二十年苦心孤詣進行奇楠嫁接的經驗與心得；從…"
