    "excerpt": "本期各篇文章從起式、收式的心法與做法，延伸至廣袤無涯的個人內在修煉，而本應在上一期刊出的專欄三〈山腳下的蘆葦〉看似與各文風格迥異，一內一外、一動一靜，然而它卻巧妙地與其他文章在無聲處悄悄交會─…"
