    "status": "approved",
    "sourceModified": "2026-08-08T03:10:34.5480000Z",
    "author": "文稿彙整、二早班",
    "id": "202605::/home/runner/work/_temp/source_articles/202605/2605-3-6如是我聞之六.docx",
