    "status": "approved",
    "sourceModified": "2026-08-08T03:39:24.6470000Z",
    "author": "文稿彙整、鄭雅靜",
    "id": "202607::/home/runner/work/_temp/source_articles/202607/2607-4體證道德經74司殺.docx",
    "issueId": "202607",
